    respond(res, 400, { error: '请求体不是有效的 JSON' });
    return;
  }
  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
    respond(res, 400, { error: '请求体必须是 JSON 对象' });
    return;
  }
