  const problem = checkIdeaContent(rawTitle, rawDescription, scenario);
  if (problem) {
    respond(res, 400, { error: CONTENT_ERROR_MESSAGES[problem] });
    return;
  }
  const { title, description } = normalizeIdea(rawTitle, rawDescription, scenario);
