  if (!['/', '/health', '/api/ideas'].includes(route)) { respond(res, 404, { error: 'not found' }); return; }
  if (route === '/api/ideas') {
    if (req.method === 'POST') {
      handleCreateIdea(req, res).catch(() => {
        if (!res.headersSent) respond(res, 500, { error: '提交意见失败，请稍后重试' });
