1	// 产品意见三个字段的唯一规则来源：首页内联脚本与 POST /api/ideas 接口共用。
2	// 上限、空白处理与码点计数只能在这里定义一次：
3	//   - 接口侧（server.ts）直接调用本模块的函数；
4	//   - 首页无法使用模块导入，server.ts 把下列同一个函数的源码（Function.prototype.toString）
5	//     注入内联脚本，因此页面执行的校验与这里逐字相同，不要在页面里再维护第二份。
6	//
7	// 规则（长度一律按 Unicode 码点计数，Array.from(text).length）：
8	//   title       必填，去掉首尾空白后非空，最多 120 个码点；内部空白保留并计入，
9	//               保存去掉首尾空白后的结果；
10	//   description 必填，须含非空白内容，最多 5000 个码点；首尾空白与换行计入长度并原样保存；
11	//   scenario    可省略（省略时按空字符串保存）；填写时为字符串，最多 1000 个码点，
12	//               按原文计数与保存。
13	// 恰好达到上限允许提交；超限由调用方拒绝整条意见，不截断。
14	
15	export const FIELD_LIMITS = {
16	  title: 120,
17	  description: 5000,
18	  scenario: 1000,
19	} as const;
20	
21	// 按 Unicode 码点计数：中文、英文字母、单个 😀 各算一个；
22	// 旗帜、ZWJ 表情、组合字符等由多个码点组成的文字按各自码点累计，
23	// 不能按 UTF-16 码元（String.length）或传输字节计数。
24	export function codePointCount(text: string): number {
25	  return Array.from(text).length;
26	}
27	
28	// 内容层面的问题类型。两个入口的提示措辞可以不同，但接受/拒绝的判定共用本结果。
29	export type ContentErrorCode =
30	  | 'title-empty'
31	  | 'title-too-long'
32	  | 'description-empty'
33	  | 'description-too-long'
34	  | 'scenario-too-long';
35	
36	// 校验三个字符串字段的内容，按首页与接口一致的顺序返回第一个问题；全部通过返回 null。
37	// 入参必须已经是字符串：字段缺失、请求体不是对象、字段类型错误属于接口的结构校验，
38	// 由 server.ts 在调用本函数之前处理（首页的输入框值天然是字符串）。
39	export function checkIdeaContent(
40	  title: string,
41	  description: string,
42	  scenario: string,
43	): ContentErrorCode | null {
44	  const trimmedTitle = title.trim();
45	  if (!trimmedTitle) return 'title-empty';
46	  if (codePointCount(trimmedTitle) > FIELD_LIMITS.title) return 'title-too-long';
47	  if (!description.trim()) return 'description-empty';
48	  if (codePointCount(description) > FIELD_LIMITS.description) return 'description-too-long';
49	  if (codePointCount(scenario) > FIELD_LIMITS.scenario) return 'scenario-too-long';
50	  return null;
